from __future__ import annotations
import argparse
import datetime as datetime
import json
import os
import platform
import re
import shutil
import sqlite3
import subprocess
import sys
import time
from pathlib import Path

REPO = "oldmangrizzz/The_Workshop_Mk1"
OWNER = "oldmangrizzz"
PVE = "root@100.98.1.114"
REMOTE = "/mnt/local-hdd/private/gmri-github-bridge/worker.py"
PREFIX = "[GMRI-BRIDGE]"
SCHEMA = "gmri.task.v1"
