DB = HOME / "queue.sqlite3"
SSH = ["ssh", "-o", "BatchMode=yes", "-o", "StrictHostKeyChecking=yes",
       "-o", "ConnectTimeout=8", PVE]
MAX_TASK_LENGTH = 24_000


def command(argv: list[str], timeout=30, input_text=None) -> subprocess.CompletedProcess:
    return subprocess.run(argv, text=True, input=input_text, capture_output=True, timeout=timeout,
                          env={**os.environ, "PATH": "/opt/homebrew/bin:/usr/local/bin:/Users/rbhanson/.bun/bin:/usr/bin:/bin:/usr/sbin:/sbin"})


def gh_json(endpoint: str, method="GET", fields=None):
    args = ["gh", "api", "--hostname", "github.com", endpoint]
    if method != "GET":
        args.extend(["--method", method, "-H", "Accept: application/vnd.github+json"])
        for key, value in (fields or {}).items():
            args.extend(["-f", f"{key}={value}"])
    r = command(args, timeout=30)
    if r.returncode:
        raise RuntimeError(f"GitHub API failed (exit {r.returncode}): {r.stderr[:200]}")
    return json.loads(r.stdout) if r.stdout.strip() else {}


def connect_db(path=DB):
    path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
    conn = sqlite3.connect(path, timeout=10)
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute("""CREATE TABLE IF NOT EXISTS jobs (
            issue INTEGER PRIMARY KEY, status TEXT NOT NULL, kind TEXT NOT NULL,
            target TEXT NOT NULL, result TEXT, reported INTEGER NOT NULL DEFAULT 0,
            updated_at TEXT NOT NULL)""")
    conn.commit()
    return conn


def accept_issue(issue):
    if "pull_request" in issue or issue.get("state") != "open":
        return None
    if not str(issue.get("title", "")).startswith(PREFIX):
        return None
    if issue.get("user", {}).get("login", "").casefold() != OWNER.casefold():
        return None
    try:
        job = json.loads(issue.get("body") or "")
    except (TypeError, ValueError):
        return None
    if not isinstance(job, dict) or job.get("schema") != SCHEMA:
        return None
    if job.get("target") not in ("mac", "proxmox"):
        return None
    kind = job.get("kind")
    if kind not in ("probe", "status", "omp_mission", "macos_harness"):
        return None
    if kind == "macos_harness" and job["target"] != "mac":
        return None
    if kind == "omp_mission" and job["target"] != "proxmox":
        return None
    if kind in ("omp_mission", "macos_harness"):
        key = "mission" if kind == "omp_mission" else "python"
        if not isinstance(job.get(key), str) or not 1 <= len(job[key]) <= MAX_TASK_LENGTH:
            return None
    return job


def redact(text):
    # Do not auto-post file contents, environment, process arguments, or secrets.
    t = str(text).replace("\x00", "")
    t = re.sub(r"(?i)(token|api[_-]?key|password|secret)\s*[:=]\s*\S+", r"\1=<redacted>", t)
    return t[-7000:]


def remote_worker(op: str, payload=None):
    argv = SSH + ["python3", REMOTE, op]
    p = command(argv, timeout=55, input_text=json.dumps(payload) if payload is not None else None)
    if p.returncode:
        raise RuntimeError(f"Proxmox worker {op} exit={p.returncode}: {redact(p.stderr[-700:])}")
    try:
        return json.loads(p.stdout)
    except ValueError as e:
        raise RuntimeError(f"Proxmox returned invalid JSON: {p.stdout[-300:]}") from e


def do_job(issue: int, job):
    target, kind = job["target"], job["kind"]
    if target == "proxmox":
        payload = {"issue": issue, "kind": kind}
        if kind == "omp_mission":
            payload["mission"] = job["mission"]
        return remote_worker("submit", payload)
    if kind in ("probe", "status"):
        disk = shutil.disk_usage(str(Path.home()))
        ans = {"target": "mac", "hostname": platform.node(), "os": platform.platform(),
               "free_gib": round(disk.free / (1024 ** 3), 2),
               "macos_harness_installed": shutil.which("macos-harness") is not None,
               "omp_locally_running": False,
               "remote_proxmox": "not_probed"}
        p = command(["pgrep", "-fl", "[o]mp --cwd"], timeout=4)
        ans["omp_locally_running"] = bool(p.stdout.strip())
        try:
            ans["remote_proxmox"] = remote_worker("probe")
        except Exception as ex:
            ans["remote_proxmox"] = {"reachable": False, "reason": redact(str(ex))}
        return ans
    if kind == "macos_harness":
        if not shutil.which("macos-harness"):
            raise RuntimeError("macos-harness is not installed; install/doctor first")
        # Exactly one authorized Python execution burst. No shell eval, no public endpoint.
        p = command(["macos-harness"], timeout=80, input_text=job["python"])
        return {"exit_code": p.returncode, "stdout": redact(p.stdout),
                "stderr": redact(p.stderr)}
    raise RuntimeError("Unknown local task")


def record_issue(conn, issue, job):
    number = issue["number"]
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()
    conn.execute("INSERT OR IGNORE INTO jobs(issue,status,kind,target,result,updated_at) VALUES (?,?,?,?,?,?)",
                 (number, "NEW", job["kind"], job["target"], None, now))
    conn.commit()
    row = conn.execute("SELECT status FROM jobs WHERE issue=?", (number,)).fetchone()
    return row[0]


def persist(conn, number, status, result=None, reported=0):
    conn.execute("UPDATE jobs SET status=?, result=?, reported=?, updated_at=? WHERE issue=?",
                 (status, json.dumps(result) if result is not None else None, reported,
                  datetime.datetime.now(datetime.timezone.utc).isoformat(), number))
    conn.commit()


def report(conn):
    pending = conn.execute("SELECT issue,status,result FROM jobs WHERE reported=0 AND status IN ('DONE','ERROR','DISPATCHED') ORDER BY issue").fetchall()
    for number, status, raw in pending:
        body = (f"GMRI_BRIDGE_RECEIPT_V1\nstatus: {status}\njob: #{number}\n"
                f"time_utc: {datetime.datetime.now(datetime.timezone.utc).isoformat()}\n"
                f"```json\n{redact(json.dumps(json.loads(raw or '{}'), indent=2))}\n```")
        gh_json(f"repos/{REPO}/issues/{number}/comments", method="POST", fields={"body": body})
        conn.execute("UPDATE jobs SET reported=1 WHERE issue=?", (number,))
        conn.commit()


def run_once(conn):
    # Never retry a DISPATCHED side effect blindly after a crash. Inspect receipt.
    issues = gh_json(f"repos/{REPO}/issues?state=open&per_page=100&sort=created&direction=asc")
    for issue in issues:
        if not isinstance(issue, dict):
            continue
        job = accept_issue(issue)
        if job is None:
            continue
        number = issue["number"]
        status = record_issue(conn, issue, job)
        if status != "NEW":
            continue
        persist(conn, number, "DISPATCHED", {"message": "Dispatch persisted before effect"})
        try:
            result = do_job(number, job)
            persist(conn, number, "DONE", result)
        except Exception as e:
            persist(conn, number, "ERROR", {"error": redact(str(e))})
    report(conn)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--once", action="store_true", help="single check for installation test")
    parser.add_argument("--poll-seconds", type=int, default=45)
    parser.add_argument("--db", type=Path, default=DB)
    args = parser.parse_args()
    conn = connect_db(args.db)
    while True:
        try:
            run_once(conn)
        except Exception as ex:
            print(datetime.datetime.now(datetime.timezone.utc).isoformat(),
                  "bridge polling failure", redact(str(ex)), file=sys.stderr, flush=True)
        if args.once:
            return 0
        time.sleep(max(20, min(180, args.poll_seconds)))

if __name__ == "__main__":
    raise SystemExit(main())
