    omp = run(['pct', 'exec', str(ctid), '--', 'sh', '-c',
               'command -v omp || test -x /root/.bun/bin/omp'], timeout=8)
    rig = run(['pct', 'exec', str(ctid), '--', 'sh', '-c', 'command -v rig'], timeout=8)
    return {'ready': check.returncode == 0 and omp.returncode == 0,
            'ctid': ctid, 'omp_installed': omp.returncode == 0,
            'openrig_installed': rig.returncode == 0,
            'workspace_mounted': check.returncode == 0,
            'reason': '' if check.returncode == 0 and omp.returncode == 0
                      else 'Need mounted guest workspace and OMP binary'}


def probe():
    try:
        total, used, free = shutil.disk_usage('/mnt/local-hdd')
        storage = {'free_gib': round(free / 1024**3, 2), 'used_gib': round(used / 1024**3, 2)}
    except OSError as exc:
        storage = {'error': str(exc)[:100]}
    return {'target': 'proxmox', 'hostname': os.uname().nodename,
            'storage': storage, 'guest': guest_info(config()),
            'bridge_installed': str(BASE)}


def status(number):
    meta = JOBS / str(number) / 'metadata.json'
    if not meta.exists():
        return {'issue': number, 'state': 'UNKNOWN'}
    data = json.loads(meta.read_text())
    if not data.get('unit') or not data.get('ctid'):
        return {'issue': number, 'state': data.get('state', 'UNKNOWN'),
                'reason': data.get('reason', ''), 'mission_sha256': data.get('mission_sha256')}
    ctid, unit = str(data['ctid']), data['unit']
    r = run(['pct', 'exec', ctid, '--', 'systemctl', 'show', unit,
             '-p', 'ActiveState', '-p', 'SubState', '-p', 'Result',
             '-p', 'ExecMainStatus', '--no-pager'], timeout=13)
    if r.returncode:
        return {'issue': number, 'state': 'UNKNOWN', 'reason': 'Guest status unavailable',
                'unit': unit, 'ctid': ctid}
    props = dict(line.split('=', 1) for line in r.stdout.splitlines() if '=' in line)
    active = props.get('ActiveState')
    if active in ('active', 'activating'):
        phase = 'RUNNING'
    elif active == 'inactive' and props.get('Result') == 'success' and props.get('ExecMainStatus') == '0':
        phase = 'DONE'
    elif active == 'failed':
        phase = 'ERROR'
    else:
        phase = 'UNKNOWN'
    return {'issue': number, 'state': phase, 'ctid': int(ctid), 'unit': unit,
            'systemd': props, 'mission_sha256': data.get('mission_sha256'),
            'log_command': f'pct exec {ctid} -- journalctl -u {unit} --no-pager'}


def submit(request):
    number = request.get('issue')
    if type(number) is not int or not 1 <= number <= 999999999:
        raise ValueError('Invalid issue number')
    kind = request.get('kind')
    if kind in ('probe', 'status'):
        return probe()
    if kind not in ('omp_mission', 'rig_send'):
        raise ValueError('Unsupported job kind')
    mission = request.get('mission')
    if not isinstance(mission, str) or not 1 <= len(mission) <= 24000:
        raise ValueError('Invalid mission')
    target = JOBS / str(number)
    metadata = target / 'metadata.json'
    if metadata.exists():
        return status(number)  # exactly one issued job; preserve uncertain results
    target.mkdir(mode=0o700, parents=True, exist_ok=True)
    digest = hashlib.sha256(mission.encode()).hexdigest()
    (target / 'mission.md').write_text(mission, encoding='utf-8')
    (target / 'mission.md').chmod(0o600)
    info = guest_info(config())
    if not info['ready']:
        atomic(metadata, {'issue': number, 'state': 'BLOCKED', 'kind': kind,
                          'reason': info['reason'], 'mission_sha256': digest})
        return status(number)
    ctid = info['ctid']
    if kind == 'rig_send' and not info['openrig_installed']:
        atomic(metadata, {'issue': number, 'state': 'BLOCKED', 'kind': kind,
                          'reason': 'OpenRig absent in designated guest', 'mission_sha256': digest})
        return status(number)
    unit = UNIT_PREFIX + str(number)
    guest_job = '/mnt/gmri-workspace/bridge-jobs/' + str(number)
    setup = run(['pct', 'exec', str(ctid), '--', 'install', '-d', '-m', '0700', guest_job], timeout=13)
    if setup.returncode:
        atomic(metadata, {'issue': number, 'state': 'BLOCKED', 'kind': kind,
                          'reason': 'Cannot create job path in guest', 'mission_sha256': digest})
        return status(number)
    push = run(['pct', 'push', str(ctid), str(target / 'mission.md'), guest_job + '/mission.md'], timeout=13)
    if push.returncode:
        atomic(metadata, {'issue': number, 'state': 'BLOCKED', 'kind': kind,
                          'reason': 'Cannot stage mission into guest', 'mission_sha256': digest})
        return status(number)
    if kind == 'omp_mission':
        argv = ['/root/.bun/bin/omp', '--cwd', '/mnt/gmri-workspace',
                '--no-title', '--max-time=4h', '-p', '@' + guest_job + '/mission.md']
    else:
        seat = request.get('seat')
        if not isinstance(seat, str) or not SEAT_RE.fullmatch(seat):
            atomic(metadata, {'issue': number, 'state': 'BLOCKED', 'kind': kind,
                              'reason': 'No valid OpenRig seat provided', 'mission_sha256': digest})
            return status(number)
        argv = ['rig', 'send', seat, mission, '--verify']
    atomic(metadata, {'issue': number, 'kind': kind, 'ctid': ctid,
                      'state': 'DISPATCHING', 'unit': unit, 'mission_sha256': digest,
                      'started_utc': dt.datetime.now(dt.timezone.utc).isoformat()})
    cmd = ['pct', 'exec', str(ctid), '--', 'systemd-run', '--unit=' + unit,
           '--property=MemoryMax=3G', '--property=CPUQuota=150%',
           '--property=RuntimeMaxSec=14400',
           '--property=WorkingDirectory=/mnt/gmri-workspace', '--', *argv]
    r = run(cmd, timeout=30)
    if r.returncode:
        # Retain DISPATCHING: a timed out dispatch may have succeeded.
        atomic(metadata, {'issue': number, 'kind': kind, 'ctid': ctid,
                          'state': 'DISPATCH_UNCERTAIN', 'unit': unit,
                          'mission_sha256': digest, 'diagnostic': r.stderr[-400:]})
        return status(number)
    return status(number)


def main():
    action = sys.argv[1] if len(sys.argv) > 1 else 'probe'
    if action == 'probe': result = probe()
    elif action == 'submit': result = submit(json.loads(sys.stdin.read(32000)))
    elif action == 'status': result = status(int(json.loads(sys.stdin.read(3000))['issue']))
    else: raise ValueError('Invalid action')
    print(json.dumps(result, sort_keys=True))

if __name__ == '__main__':
    try:
        main()
    except Exception as exc:
        print(json.dumps({'state': 'ERROR', 'error': str(exc)[:200]}), file=sys.stderr)
        raise SystemExit(1)
